void ztt_16384_4_8_8_4_4_4_fwd_dest_avx2(const double *zin, double *zout, double *plane, const double *tw, const size_t *rb, size_t tile)
{
    double *W = zout;   /* dest: the whole pipeline runs in the destination */
    (void)plane;
    _zt0tp4f_body(zin, W, rb, (size_t)4096, (size_t)4096);
    if (tile)
    {
        const size_t ntile = (size_t)16384 / tile;
#pragma GCC unroll 1
        for (size_t t = 0; t < ntile; t++)
        {
            double *B = W + t * tile * 2;
            if ((size_t)32 <= tile)   /* stage 1: R*L = 32 */
            {
#pragma GCC unroll 1
                for (size_t g = 0; g < tile / (size_t)32; g++)
                    _ztmg8f_body(B + g * (size_t)64, B + g * (size_t)64, tw + 0, (size_t)4, (size_t)4);
            }
            if ((size_t)256 <= tile)   /* stage 2: R*L = 256 */
            {
#pragma GCC unroll 1
                for (size_t g = 0; g < tile / (size_t)256; g++)
                    _ztmg8f_body(B + g * (size_t)512, B + g * (size_t)512, tw + 56, (size_t)32, (size_t)32);
            }
            if ((size_t)1024 <= tile)   /* stage 3: R*L = 1024 */
            {
#pragma GCC unroll 1
                for (size_t g = 0; g < tile / (size_t)1024; g++)
                    _ztmg4f_body(B + g * (size_t)2048, B + g * (size_t)2048, tw + 504, (size_t)256, (size_t)256);
            }
            if ((size_t)4096 <= tile)   /* stage 4: R*L = 4096 */
            {
#pragma GCC unroll 1
                for (size_t g = 0; g < tile / (size_t)4096; g++)
                    _ztmg4f_body(B + g * (size_t)8192, B + g * (size_t)8192, tw + 2040, (size_t)1024, (size_t)1024);
            }
        }
    }
    if ((size_t)32 > tile)   /* stage 1: R*L = 32 */
    {
#pragma GCC unroll 1
        for (size_t g = 0; g < (size_t)512; g++)
            _ztmg8f_body(W + g * (size_t)64, W + g * (size_t)64, tw + 0, (size_t)4, (size_t)4);
    }
    if ((size_t)256 > tile)   /* stage 2: R*L = 256 */
    {
#pragma GCC unroll 1
        for (size_t g = 0; g < (size_t)64; g++)
            _ztmg8f_body(W + g * (size_t)512, W + g * (size_t)512, tw + 56, (size_t)32, (size_t)32);
    }
    if ((size_t)1024 > tile)   /* stage 3: R*L = 1024 */
    {
#pragma GCC unroll 1
        for (size_t g = 0; g < (size_t)16; g++)
            _ztmg4f_body(W + g * (size_t)2048, W + g * (size_t)2048, tw + 504, (size_t)256, (size_t)256);
    }
    if ((size_t)4096 > tile)   /* stage 4: R*L = 4096 */
    {
#pragma GCC unroll 1
        for (size_t g = 0; g < (size_t)4; g++)
            _ztmg4f_body(W + g * (size_t)8192, W + g * (size_t)8192, tw + 2040, (size_t)1024, (size_t)1024);
    }
    _ztlf4f_body(W, zout, tw + 8184, (size_t)4096, (size_t)4096, (size_t)4096);
}

